-- Редакція 1.3 (правки monobank О1–О13; юрист і бухгалтер погодили 25.11.2026): усі п'ять документів.
-- Реальних авторів і учасників ще немає — чинна з дня публікації, без 14 днів. Ідемпотентно.
begin;
update public.legal_documents set is_current = false where is_current and document in ('author_agreement', 'terms', 'participant_agreement', 'refunds', 'privacy') and version <> '1.3';
insert into public.legal_documents (document, version, text_hash, effective_from, changes_summary, is_current) values ('author_agreement', '1.3', '571d94252ee7c2f613f465d382de837815e0b4ba83c074571d875de294747d23', now(), 'Правки monobank: тариф сплачується дебетовими переказами з рахунку Автора за його дорученням банку; комісію банку з договору прибрано; розділ «Тариф»', true) on conflict (document, version) do update set text_hash = excluded.text_hash, is_current = true;
insert into public.legal_documents (document, version, text_hash, effective_from, changes_summary, is_current) values ('terms', '1.3', 'efe6a24cde535089a12f82fd642da3899ce4e5f5e369415b85936a8a3fc06ab0', now(), '«Розрахунки з автором»: тариф перераховується з рахунку Автора на рахунок Sensoria через банк-еквайєр', true) on conflict (document, version) do update set text_hash = excluded.text_hash, is_current = true;
insert into public.legal_documents (document, version, text_hash, effective_from, changes_summary, is_current) values ('participant_agreement', '1.3', '8c0cfc8cae45df2b26b9a58342e455f47f536fd1858d718b37819dbd5afe7ce3', now(), '6.3: оплата надходить на рахунок автора, тариф автор сплачує Оператору зі свого рахунку', true) on conflict (document, version) do update set text_hash = excluded.text_hash, is_current = true;
insert into public.legal_documents (document, version, text_hash, effective_from, changes_summary, is_current) values ('refunds', '1.3', 'c2b16cc3113fc71ab0f8ea65f7f80655ef7848d3915f75b881801f19ebc76b6b', now(), 'Редакційна правка: прибрано згадку про розподіл оплати', true) on conflict (document, version) do update set text_hash = excluded.text_hash, is_current = true;
insert into public.legal_documents (document, version, text_hash, effective_from, changes_summary, is_current) values ('privacy', '1.3', 'fb34dd1c9fda71958215f747314b6660b0548cf866a79ee54eab788e4233a479', now(), 'Редакційна правка: «розподіл коштів» замінено на «перерахування тарифу Sensoria з рахунку автора»', true) on conflict (document, version) do update set text_hash = excluded.text_hash, is_current = true;
commit;
